import java.util.Scanner;

public class Main {
    static final int SZ = 510;
    static long MOD;

    static long pairVal(long x) {
        return (x * (x - 1) / 2) % MOD;
    }

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int N = sc.nextInt();
        int M = sc.nextInt();
        MOD = sc.nextLong();

        long[][] comb = new long[SZ][SZ];
        for (int i = 0; i < SZ; i++) {
            comb[i][0] = 1;
        }
        for (int i = 1; i < SZ; i++) {
            for (int j = 1; j <= i; j++) {
                comb[i][j] = (comb[i-1][j-1] + comb[i-1][j]) % MOD;
            }
        }

        long[] fArr = new long[SZ];
        long[] gArr = new long[SZ];
        fArr[0] = 0;
        gArr[0] = 1;

        for (int i = 1; i <= M; i++) {
            for (int j = 1; j <= i; j++) {
                long mul = comb[i-1][j-1];
                long a1 = ((((mul * fArr[j-1]) % MOD) * gArr[i-j]) % MOD) * (i+1) % MOD;
                long a2 = ((((mul * gArr[j-1]) % MOD) * fArr[i-j]) % MOD) * (i+1) % MOD;
                long a3 = ((((mul * gArr[j-1]) % MOD) * gArr[i-j]) % MOD) * ((pairVal(j) + pairVal(i-j+1)) % MOD) % MOD;
                fArr[i] = (fArr[i] + (a1 + a2 + a3) % MOD) % MOD;
                long g = ((((mul * gArr[j-1]) % MOD) * gArr[i-j]) % MOD) * (i+1) % MOD;
                gArr[i] = (gArr[i] + g) % MOD;
            }
        }

        long[][] dp = new long[SZ][SZ];
        long[][] ways = new long[SZ][SZ];
        long[][] dpPrev = new long[SZ][SZ];
        long[][] waysPrev = new long[SZ][SZ];
        dp[0][0] = 0;
        ways[0][0] = 1;

        for (int i = 0; i < N; i++) {
            long[][] dpTmp = new long[SZ][SZ];
            long[][] waysTmp = new long[SZ][SZ];
            int upperJ = Math.min(i, M);
            for (int j = 0; j <= upperJ; j++) {
                int upperK = Math.min(j, M);
                for (int k = 0; k <= upperK; k++) {
                    if (k == 0) {
                        dpPrev[i][j] = dp[j][0];
                        waysPrev[i][j] = ways[j][0];
                    }
                    dpTmp[j][0] = (dpTmp[j][0] + dp[j][k]) % MOD;
                    waysTmp[j][0] = (waysTmp[j][0] + ways[j][k]) % MOD;
                    int rem = M - (j - k);
                    long w = (((waysPrev[i-k][j-k] * comb[rem][k+1]) % MOD) * gArr[k+1]) % MOD;
                    waysTmp[j+1][k+1] = (waysTmp[j+1][k+1] + w) % MOD;
                    long b1 = (((dpPrev[i-k][j-k] * comb[rem][k+1]) % MOD) * gArr[k+1]) % MOD;
                    long b2 = (((waysPrev[i-k][j-k] * comb[rem][k+1]) % MOD) * fArr[k+1]) % MOD;
                    dpTmp[j+1][k+1] = (dpTmp[j+1][k+1] + (b1 + b2) % MOD) % MOD;
                }
            }
            for (int j = 0; j < SZ; j++) {
                for (int k = 0; k < SZ; k++) {
                    dp[j][k] = dpTmp[j][k];
                    ways[j][k] = waysTmp[j][k];
                }
            }
        }

        long res = 0;
        for (int j = 0; j <= M; j++) {
            res = (res + dp[M][j]) % MOD;
        }
        System.out.println(res);
        sc.close();
    }
}
